import java.util.*;
import java.util.stream.*;

class User {
    private Optional<String> email;
    public User(String email) { this.email = Optional.ofNullable(email); }
    public Optional<String> getEmail() { return email; }
}

public class EmailCollector {
    public static void main(String[] args) {
        List<User> users = Arrays.asList(
            new User("alice@example.com"),
            new User(null),
            new User("bob@example.com")
        );

        Set<String> emails = users.stream()
            .map(User::getEmail)        // Stream<Optional<String>>
            .flatMap(Optional::stream)  // flatten only present values
            .collect(Collectors.toSet());

        System.out.println(emails);
    }
}
